it('returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round', async () => {
  const registry = new ToolRegistry();
  let executorCalls = 0;
  registry.register(
    {
      name: 'weather_service',
      description: 'Check current weather',
      inputSchema: {
        type: 'object',
        properties: {location: {type: 'string'}},
        required: ['location'],
      },
    },
    async () => {
      executorCalls++;
      return 'Sunny';
    }
  );

  const capturedParams: SendMessageParams[] = [];
  const provider: AIProvider = {
    async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
      capturedParams.push(JSON.parse(JSON.stringify(params)));
      const round = capturedParams.length;
      if (round === 1) {
        yield {type: 'tool_use', toolCall: {id: 'call_1', name: 'weather_service', input: {}}};
        yield STOP_FOR_TOOL;
        return;
      }
      if (round === 2) {
        yield {type: 'tool_use', toolCall: {id: 'call_2', name: 'weather_service', input: {location: 'London'}}};
        yield STOP_FOR_TOOL;
        return;
      }
      yield {type: 'text', text: 'It is sunny.'};
      yield STOP_DONE;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };

  const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);
  const result = await orchestrator.processMessage(createSession('ask'));

  const round2Last = capturedParams[1].messages[capturedParams[1].messages.length - 1];
  const round3Last = capturedParams[2].messages[capturedParams[2].messages.length - 1];

  expect({
    result,
    executorCalls,
    round2: {
      role: round2Last.role,
      content: Array.isArray(round2Last.content) ? round2Last.content[0] : round2Last.content,
    },
    round3: {
      role: round3Last.role,
      content: Array.isArray(round3Last.content) ? round3Last.content[0] : round3Last.content,
    },
  }).toMatchObject({
    result: 'It is sunny.',
    executorCalls: 1,
    round2: {
      role: 'user',
      content: {type: 'tool_result', content: expect.stringMatching(/location.*required/i)},
    },
    round3: {
      role: 'user',
      content: {type: 'tool_result', content: 'Sunny'},
    },
  });
});

